insert into app.roles(code,name_th,name_en) values ('VIEWER','ผู้ดูข้อมูล','Viewer'),('EXECUTIVE','ผู้บริหาร','Executive'),('DATA_ENTRY','ผู้บันทึกข้อมูล','Data Entry'),('ADMIN','ผู้ดูแลระบบ','Admin') on conflict(code) do nothing;
insert into app.permissions(code,description) values ('financial.view','View financial data'),('financial.create','Create draft financial records'),('financial.update','Update eligible drafts'),('financial.submit','Submit records'),('financial.approve','Approve records'),('financial.adjust','Create adjustments and reversals'),('reconciliation.review','Review reconciliation'),('import.create','Create import batches'),('import.approve','Approve imports'),('audit.view','View audit records'),('admin.manage','Manage configuration') on conflict(code) do nothing;
insert into app.role_permissions(role_id,permission_id) select r.id,p.id from app.roles r cross join app.permissions p where (r.code='VIEWER' and p.code='financial.view') or (r.code='EXECUTIVE' and p.code in('financial.view','reconciliation.review')) or (r.code='DATA_ENTRY' and p.code in('financial.view','financial.create','financial.update','financial.submit','import.create')) or r.code='ADMIN' on conflict do nothing;
