begin;
select y.id,yp.id,v.code,'QUARTER',v.source_label,v.label,v.label,v.ord,jsonb_build_object('calendar_mapping','UNCONFIRMED','safe_seed',true,'source_availability',case when v.source_label is null then 'NOT_AVAILABLE' else 'AVAILABLE' end)
from app.reporting_years y join app.reporting_periods yp on yp.reporting_year_id=y.id and yp.period_type='YEAR'
join(values('Y68','Q1-68','Q1/68',null,1),('Y68','Q2-68','Q2/68',null,2),('Y68','Q3-68','Q3/68','Q3/68',3),('Y68','Q4-68','Q4/68','Q4/68',4),('Y69','Q1-69','Q1/69','Q1/69',1),('Y69','Q2-69','Q2/69','Q2/69',2),('Y69','Q3-69','Q3/69',null,3),('Y69','Q4-69','Q4/69',null,4))v(ycode,code,label,source_label,ord) on v.ycode=y.code on conflict(period_code) do nothing;
commit;
